ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / 'level_factory'
PINS = {'CHANGELOG.md': 'bccfdc2365064f3a', 'VERSION': 'fe21e903e11e8393', 'packages/pipeline/road_grammar.py': '8f6c94217109fdb8', 'packages/service/design.py': 'b66fb7d83180bf1d', 'tests/service/test_design.py': 'e0bcd40d1d6bb193', 'tests/unit/test_road_grammar.py': '17286a7f7dc1b1af'}
EDITS = {'CHANGELOG.md': [('lines 1-1', "## [0.262.2] - `contracts.GROUNDED`'s deli_counter row re-grounded for factory 1.42.1\n", '## [0.263.0] - the Delco Ave template, and a road grammar of one street\n\nThe walker, of the authoring panel\'s one template: "restaurant block doesnt feel right ... Try Delco Ave (for a simple\n1 lane road level template)", then "my goal is to have like 8 of those templates with great diversity/dynamics".\n\n### Added\n- **The `avenue` road grammar** (`road_grammar.GRAMMARS`; spellings `avenue`, `ave`, `one_road`, `single_road`): ONE\n  road, the T\'s front road across the plate with every front door\'s spur to it, and no cross street -- the main\n  street this module\'s docstring named as a shape a person asks for and it could not build. The plate is not\n  widened for a cross line that is not there. `main_street`, `strip` and `street` still mean T: briefs and levels\n  on disk wrote them, and re-pointing a spelling would move every one.\n- **The Delco Ave template** (`packages/service/templates/delco_ave.json`): four buildings along one avenue, one lane\n  each way and no junction, anchored on a corner convenience store, evening; its Streets control defaults to the\n  avenue.\n- The panel\'s Streets labels say what each is: "A T junction" (it read "One street"), "One street, no junction (an\n  avenue)".\n\n### Measured\n- Delco Ave made and walked from the panel\'s own brief (`design.brief_from_design`), with nobody touching anything:\n  make 7.8 min, seed 9003 shipped at PASS 90 (9104 PASS_WITH_TUNING 84, 9205 PASS_WITH_TUNING 88); the site\'s one\n  road 219 m by 10 m; walk exit 0, both ladders climbed, five stations passed; the closure ok over 86 resources.\n- Its first make refused every candidate: Deli Counter\'s IP-name guard read \'delco\' in the level\'s own name\n  (`lf_delco_ave_001_9003`). Deli Counter 0.287.1 holds a designer\'s level name to it no longer; this release needs\n  it.\n\n### Tests\n- `tests/unit/test_road_grammar.py`: an avenue is the front road alone, its doors the T\'s; the old spellings stay T\n  (fails on 0.262.2).\n- `tests/service/test_design.py`: Delco Ave is listed, its Streets default the avenue, and only the avenue\'s label\n  says one street.\n\n## [0.262.2] - `contracts.GROUNDED`\'s deli_counter row re-grounded for factory 1.42.1\n')], 'VERSION': [('lines 1-1', '0.262.2', '0.263.0')], 'packages/pipeline/road_grammar.py': [('lines 82-82', 'GRAMMARS = ("T", "cross", "block")\n', '#: `avenue` (0.263.0, the walker: "Try Delco Ave (for a simple 1 lane road level template)"): ONE road, the T\'s\n#: front road with its doors\' spurs and no cross street -- the main street this module\'s docstring names as a shape\n#: it could not build. `main_street`, `strip` and `street` still mean T: briefs and levels on disk wrote them, and\n#: re-pointing a spelling would move every one of them.\nGRAMMARS = ("T", "cross", "block", "avenue")\n'), ('lines 94-95', '    "rear_lane": "block", "alley": "block", "back_lane": "block",\n}\n', '    "rear_lane": "block", "alley": "block", "back_lane": "block",\n    "avenue": "avenue", "ave": "avenue", "one_road": "avenue", "single_road": "avenue",\n}\n'), ('lines 366-367', '    road, y_road, span_y = _through_road(south, span_x, span_y)\n    x_cross, span_x, flank = _cross_line(edges, span_x)\n', '    road, y_road, span_y = _through_road(south, span_x, span_y)\n    if shape == "avenue":\n        # ONE ROAD (0.263.0): the front road across the plate as it stands, every front door\'s spur to it, and no\n        # cross line -- `_cross_line` would widen the plate for a street that is not there\n        return [road], _spurs(faces, y_road), span_x, span_y\n    x_cross, span_x, flank = _cross_line(edges, span_x)\n')], 'packages/service/design.py': [('lines 75-76', '_GRAMMAR_LABELS = {"T": "One street (a T junction)", "cross": "Crossroads",\n                   "block": "A block with a service lane behind (a loop)"}\n', '_GRAMMAR_LABELS = {"T": "A T junction", "cross": "Crossroads",\n                   "block": "A block with a service lane behind (a loop)",\n                   "avenue": "One street, no junction (an avenue)"}\n')], 'tests/service/test_design.py': [('lines 153-154', '    assert [t["template_id"] for t in operations.list_templates({}, _NOOP)["templates"]] == [T]\n    assert operations.describe_template({"template": T}, _NOOP)["controls"]\n', '    # Delco Ave (0.263.0): one street, the avenue grammar\'s template\n    assert [t["template_id"] for t in operations.list_templates({}, _NOOP)["templates"]] == ["delco_ave", T]\n    assert operations.describe_template({"template": T}, _NOOP)["controls"]\n\n\ndef test_delco_ave_is_one_street():\n    """0.263.0, the walker: "Try Delco Ave (for a simple 1 lane road level template)". Its Streets control defaults\n    to the avenue grammar, which lays the front road alone; the T it was nearest to keeps its cross street."""\n    c = design._controls("delco_ave")\n    assert c["road_grammar"]["default"] == "avenue"\n    assert design.template("delco_ave")["label"] == "Delco Ave"\n    labels = {o["value"]: o["label"] for o in c["road_grammar"]["options"]}\n    assert labels["avenue"].startswith("One street") and not labels["T"].startswith("One street")\n')], 'tests/unit/test_road_grammar.py': [('lines 351-351', '    assert not any(a.control == "signal" for a in site_streets.approaches(resolved) if 3 in (a.road, a.crosser))\n', '    assert not any(a.control == "signal" for a in site_streets.approaches(resolved) if 3 in (a.road, a.crosser))\n\n\ndef test_an_avenue_is_the_front_road_alone():\n    """0.263.0: the T\'s front road and its doors\' spurs, no cross street, the plate not widened for one."""\n    b, fp = _buildings(n=4)\n    t_roads, t_doors, t_x, t_y = rg.roads_for("T", b, fp, 200, 120)\n    a_roads, a_doors, a_x, a_y = rg.roads_for("avenue", b, fp, 200, 120)\n    assert len(a_roads) == 1 and len(t_roads) >= 2\n    assert a_roads[0]["a"][1] == t_roads[0]["a"][1] and a_roads[0]["width"] == rg.ROAD_WIDTH\n    assert a_y == t_y and a_x <= t_x\n    assert a_doors and all(d in t_doors for d in a_doors)\n    for spelling in ("avenue", "ave", "one_road", "single_road"):\n        assert rg.grammar_of(spelling) == "avenue"\n    for spelling in ("main_street", "strip", "street"):        # what briefs on disk wrote stays a T\n        assert rg.grammar_of(spelling) == "T"\n')]}
WHOLE = {}
NEW_FILES = {'packages/service/templates/delco_ave.json': '{\n  "schema": "gabagool.template.v1",\n  "template_id": "delco_ave",\n  "label": "Delco Ave",\n  "description": "One street and nothing else: four buildings along a Delco avenue, one lane each way and no junction, anchored on a corner convenience store. In the front, through the back room to the safe, and out to the curb.",\n  "batch": {\n    "seed_base": 9003,\n    "theme_family": "delco"\n  },\n  "brief": {\n    "schema": "level_factory.mission_brief.v0.1",\n    "archetype": "convenience_store",\n    "building_count": 4,\n    "site_shape": "strip",\n    "road_grammar": "avenue",\n    "route_shape": "linear_push",\n    "objective_hypotheses": [\n      "enter_store",\n      "reach_back_room",\n      "crack_safe",\n      "extract"\n    ],\n    "extraction_relationship": "street_getaway",\n    "verticality": "low",\n    "landmark": "neon_sign",\n    "time_of_day": "evening",\n    "weather": "clear",\n    "theme": "delco_1997",\n    "candidate_count": 3,\n    "target_minutes": [\n      20,\n      30\n    ]\n  }\n}\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
